import random, itertools, time, math
n=28; d=4

def random_reg(n,d):
    stubs=[]
    for i in range(n): stubs += [i]*d
    for attempt in range(1000):
        random.shuffle(stubs)
        edges=set(); ok=True
        for a,b in zip(stubs[::2], stubs[1::2]):
            if a==b: ok=False; break
            e=(a,b) if a<b else (b,a)
            if e in edges: ok=False; break
            edges.add(e)
        if ok: return edges
    return None

def girth_ok(edges):
    adj=[set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    # triangles
    for u in range(n):
        for v in adj[u]:
            if v>u:
                if adj[u] & adj[v]: return False,3
    # BFS girth
    best=999
    for s in range(n):
        dist=[-1]*n; par=[-1]*n; dist[s]=0
        q=[s]
        for x in q:
            if dist[x]>=3: continue # for cycles <=5 maybe depth? full ok
            for y in adj[x]:
                if dist[y]<0:
                    dist[y]=dist[x]+1; par[y]=x; q.append(y)
                elif par[x]!=y and par[y]!=x:
                    cyc=dist[x]+dist[y]+1
                    if cyc<best: best=cyc
                    if cyc<6: return False,cyc
    return True,best

start=time.time(); count=0
while time.time()-start<50:
    E=random_reg(n,d); count+=1
    if E is None: continue
    ok,g=girth_ok(E)
    if ok:
        print('FOUND', count, 'girth', g, 'edges', sorted(E)); break
else:
    print('not found', count)

